resultDisplay.originalContent:
param(
  [Parameter(Mandatory=$true)][string]$Root,
  [Parameter(Mandatory=$true)][string]$CutoffUtc,
  [Parameter(Mandatory=$true)][string]$OutFile
)
$ErrorActionPreference = 'Stop'
$root = (Resolve-Path $Root).Path
$cutoff = [datetimeoffset]::Parse($CutoffUtc, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::AssumeUniversal).UtcDateTime
$lines = @()
Get-ChildItem -LiteralPath $root -Recurse -File | ForEach-Object {
  $rel = $_.FullName.Substring($root.Length + 1).Replace('\', '/')
  if ($rel -eq 'runs/server-events.jsonl') {
    # Audit log is append-only; reconstruct its content as of the cutoff by
    # keeping only lines whose embedded timestamp is <= cutoff.
    $kept = Get-Content -LiteralPath $_.FullName | Where-Object {
      if ($_ -match '"timestamp":\s*"([^"]+)"') {
        $ts = [datetimeoffset]::Parse($Matches[1], [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::AssumeUniversal).UtcDateTime
        $ts -le $cutoff
      } else { $true }
    }
    $content = ($kept -join "`r`n")
    $h = [System.BitConverter]::ToString([System.Security.Cryptography.SHA256]::Create().ComputeHash([System.Text.Encoding]::UTF8.GetBytes($content))).Replace('-', '').ToLowerInvariant()
    $lines += "$rel|$($content.Length)|$h"
  } elseif ($_.LastWriteTimeUtc -le $cutoff) {
    $h = (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()
    $lines += "$rel|$($_.Length)|$h"
  }
}
$lines = $lines | Sort-Object
$digest = [System.BitConverter]::ToString(
  [System.Security.Cryptography.SHA256]::Create().ComputeHash(
    [System.Text.Encoding]::UTF8.GetBytes(($lines -join "`n"))
  )
).Replace('-', '').ToLowerInvariant()
$out = [ordered]@{
  root = $root
  cutoff_utc = $cutoff.ToString('o')
  computed_at_utc = (Get-Date).ToUniversalTime().ToString('o')
  file_count = $lines.Count
  tree_sha256 = $digest
}
$out | ConvertTo-Json | Set-Content -LiteralPath $OutFile -Encoding UTF8
Write-Output "reconstructed_files=$($lines.Count) tree_sha256=$digest"

